#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define TILE_M 64
#define TILE_N 64
#define K_SIZE 32

// Optimized kernel for tall-skinny matrix multiplication
// A: (M, K), B: (K, M), C: (M, M) where K is small (32)
__global__ void tall_skinny_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K) {

    // Each block computes a TILE_M x TILE_N tile of C
    int row_start = blockIdx.y * TILE_M;
    int col_start = blockIdx.x * TILE_N;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Thread computes multiple elements
    int row = row_start + ty;
    int col = col_start + tx;

    // Shared memory for A tile and B tile
    __shared__ float As[TILE_M][K_SIZE];
    __shared__ float Bs[K_SIZE][TILE_N];

    // Load A tile into shared memory (each thread loads multiple elements)
    // A is M x K
    for (int k = tx; k < K_SIZE; k += blockDim.x) {
        if (row < M && k < K) {
            As[ty][k] = A[row * K + k];
        } else {
            As[ty][k] = 0.0f;
        }
    }

    // Load B tile into shared memory
    // B is K x M
    for (int k = ty; k < K_SIZE; k += blockDim.y) {
        if (k < K && col < M) {
            Bs[k][tx] = B[k * M + col];
        } else {
            Bs[k][tx] = 0.0f;
        }
    }

    __syncthreads();

    // Compute dot product
    if (row < M && col < M) {
        float sum = 0.0f;
        #pragma unroll
        for (int k = 0; k < K_SIZE; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }
        C[row * M + col] = sum;
    }
}

torch::Tensor tall_skinny_matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::empty({M, M}, A.options());

    dim3 block(TILE_N, TILE_M);
    dim3 grid((M + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);

    tall_skinny_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
