#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define TILE_M 128
#define TILE_N 128
#define K_SIZE 32
#define BLOCK_X 16
#define BLOCK_Y 16
#define ELEMS_PER_THREAD_X 8
#define ELEMS_PER_THREAD_Y 8

// Optimized kernel for tall-skinny matrix multiplication
// A: (M, K), B: (K, M), C: (M, M) where K is small (32)
// Each thread computes ELEMS_PER_THREAD_X * ELEMS_PER_THREAD_Y elements
__global__ void tall_skinny_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K) {

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each block computes TILE_M x TILE_N tile of C
    int row_base = by * TILE_M;
    int col_base = bx * TILE_N;

    // Shared memory
    __shared__ float As[TILE_M][K_SIZE + 1]; // +1 to avoid bank conflicts
    __shared__ float Bs[K_SIZE][TILE_N + 1];

    // Each thread loads multiple elements into shared memory
    int tid = ty * BLOCK_X + tx;
    int num_threads = BLOCK_X * BLOCK_Y;

    // Load A tile (TILE_M x K)
    for (int i = tid; i < TILE_M * K_SIZE; i += num_threads) {
        int row_local = i / K_SIZE;
        int k = i % K_SIZE;
        int row_global = row_base + row_local;
        if (row_global < M && k < K) {
            As[row_local][k] = A[row_global * K + k];
        } else {
            As[row_local][k] = 0.0f;
        }
    }

    // Load B tile (K x TILE_N)
    for (int i = tid; i < K_SIZE * TILE_N; i += num_threads) {
        int k = i / TILE_N;
        int col_local = i % TILE_N;
        int col_global = col_base + col_local;
        if (k < K && col_global < M) {
            Bs[k][col_local] = B[k * M + col_global];
        } else {
            Bs[k][col_local] = 0.0f;
        }
    }

    __syncthreads();

    // Each thread computes ELEMS_PER_THREAD_Y x ELEMS_PER_THREAD_X elements
    float acc[ELEMS_PER_THREAD_Y][ELEMS_PER_THREAD_X];
    #pragma unroll
    for (int i = 0; i < ELEMS_PER_THREAD_Y; i++) {
        #pragma unroll
        for (int j = 0; j < ELEMS_PER_THREAD_X; j++) {
            acc[i][j] = 0.0f;
        }
    }

    // Compute
    #pragma unroll
    for (int k = 0; k < K_SIZE; k++) {
        float a_vals[ELEMS_PER_THREAD_Y];
        float b_vals[ELEMS_PER_THREAD_X];

        // Load A values for this thread's rows
        #pragma unroll
        for (int i = 0; i < ELEMS_PER_THREAD_Y; i++) {
            int row_local = ty * ELEMS_PER_THREAD_Y + i;
            a_vals[i] = As[row_local][k];
        }

        // Load B values for this thread's columns
        #pragma unroll
        for (int j = 0; j < ELEMS_PER_THREAD_X; j++) {
            int col_local = tx * ELEMS_PER_THREAD_X + j;
            b_vals[j] = Bs[k][col_local];
        }

        // Outer product accumulation
        #pragma unroll
        for (int i = 0; i < ELEMS_PER_THREAD_Y; i++) {
            #pragma unroll
            for (int j = 0; j < ELEMS_PER_THREAD_X; j++) {
                acc[i][j] += a_vals[i] * b_vals[j];
            }
        }
    }

    // Store results
    #pragma unroll
    for (int i = 0; i < ELEMS_PER_THREAD_Y; i++) {
        #pragma unroll
        for (int j = 0; j < ELEMS_PER_THREAD_X; j++) {
            int row_global = row_base + ty * ELEMS_PER_THREAD_Y + i;
            int col_global = col_base + tx * ELEMS_PER_THREAD_X + j;
            if (row_global < M && col_global < M) {
                C[row_global * M + col_global] = acc[i][j];
            }
        }
    }
}

