    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::empty({M, M}, A.options());

    // Use vectorized kernel
    dim3 block(32, 8);  // 256 threads per block
    // Each thread handles 4 columns
    dim3 grid(((M / 4) + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    tall_skinny_matmul_kernel_vec4<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
